import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
// ElevenLabs' API as Volter Harness (sdk/voice/providers/setup.mjs, elevenlabs.mjs) and Raiku's voice server
// (voice/tts_server.py) call it: plain HTTPS with the xi-api-key header.
const key = process.env.ELEVENLABS_API_KEY;
if (!key) throw new Error('ELEVENLABS_API_KEY is not set');
const api = 'https://api.elevenlabs.io';
const receiptFile = 'elevenlabs-records.json';
async function call(method, path, body, accept) {
  const response = await fetch(`${api}${path}`, { method, headers: { 'xi-api-key': key, ...(body ? { 'content-type': 'application/json' } : {}), ...(accept ? { accept } : {}) }, body: body ? JSON.stringify(body) : undefined, signal: AbortSignal.timeout(30_000) });
  if (!response.ok) throw new Error(`${method} ${path} answered ${response.status}: ${(await response.text()).slice(0, 300)}`);
  return response;
}
const RACHEL = '21m00Tcm4TlvDq8ikWAM';
if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  const agent = await (await call('GET', `/v1/convai/agents/${encodeURIComponent(saved.agent)}`)).json();
  assert.equal(agent.agent_id, saved.agent);
  assert.equal(agent.name, 'supercode voice: Ada');
  assert.equal(agent.conversation_config.tts.model_id, 'eleven_flash_v2');
  assert.equal(agent.conversation_config.tts.agent_output_audio_format, 'pcm_24000');
  assert.equal(agent.conversation_config.agent.prompt.custom_llm.api_key.secret_id, saved.secret);
  assert.deepEqual(agent.conversation_config.agent.prompt.tools.map((t) => t.name), ['delegate', 'hand_off']);
  assert.equal(agent.platform_settings.auth.enable_auth, true);
  const { secrets } = await (await call('GET', '/v1/convai/secrets')).json();
  const secret = secrets.find((s) => s.secret_id === saved.secret);
  assert.ok(secret, 'the workspace secret is retained');
  assert.equal(secret.name, 'ADA_LLM_TOKEN');
  assert.equal(secret.value, undefined);
  assert.ok(secret.used_by.agents.some((a) => a.agent_id === saved.agent), 'the secret names the agent that uses it');
  console.log(JSON.stringify({ retained: true, ...saved }));
} else {
  // Raiku's voice server speaks a line: Flash v2.5, raw 16-bit PCM at 24 kHz
  const speech = await call('POST', `/v1/text-to-speech/${RACHEL}?output_format=pcm_24000`, { text: 'Doors open at a quarter to six.', model_id: 'eleven_flash_v2_5' }, 'audio/pcm');
  const pcm = new Uint8Array(await speech.arrayBuffer());
  assert.equal(speech.headers.get('content-type'), 'audio/pcm');
  assert.equal(speech.headers.get('character-cost'), '31');
  assert.ok(pcm.length > 24_000 && pcm.length % 2 === 0, `PCM samples of the line's length: ${pcm.length} bytes`);
  // the custom voice server's credential, stored as a workspace secret the agent references
  const secret = await (await call('POST', '/v1/convai/secrets', { type: 'new', name: 'ADA_LLM_TOKEN', value: 'world-elevenlabs-ada-throwaway' })).json();
  assert.equal(secret.type, 'stored');
  assert.ok(secret.secret_id);
  // setup-elevenlabs provisions Ada's voice agent, as provisionElevenLabs sends it
  const tool = (name, description, properties, required) => ({ type: 'client', name, description, parameters: { type: 'object', properties, required }, expects_response: true, response_timeout_secs: 30 });
  const made = await (await call('POST', '/v1/convai/agents/create', { name: 'supercode voice: Ada', conversation_config: {
    agent: { first_message: '', language: 'en', prompt: { prompt: 'You are Ada, the realtime voice of your existing coding session, speaking as that same agent in first person.', llm: 'custom-llm',
      custom_llm: { api_type: 'chat_completions', url: 'https://voice.tidewater.example/v1', model_id: 'ada-voice', api_key: { secret_id: secret.secret_id } },
      tools: [
        tool('delegate', 'Ask your existing coding session to do work or supply facts unavailable in this voice conversation.', { task: { type: 'string', description: 'The concrete work to send to this agent’s existing coding session.' } }, ['task']),
        tool('hand_off', 'Ask the meeting to give another seated agent the floor.', { to: { type: 'string', description: 'The exact seated agent ID from the meeting context, not its display name.' }, why: { type: 'string', description: 'Why that agent should take over the asking person’s current question.' } }, ['to', 'why']),
      ] } },
    tts: { voice_id: RACHEL, model_id: 'eleven_flash_v2', agent_output_audio_format: 'pcm_24000' },
    conversation: { max_duration_seconds: 3600, client_events: ['audio', 'agent_response', 'agent_response_complete', 'client_tool_call', 'interruption'] },
  }, platform_settings: { auth: { enable_auth: true }, overrides: { conversation_config_override: { agent: { prompt: { prompt: true }, first_message: true }, tts: { voice_id: true } } } } })).json();
  assert.match(made.agent_id, /^agent_/);
  // a voice joining a call asks a signed URL for the agent
  const { signed_url: url } = await (await call('GET', `/v1/convai/conversation/get-signed-url?agent_id=${encodeURIComponent(made.agent_id)}`)).json();
  assert.match(url, /^wss?:\/\/[^/]+\/v1\/convai\/conversation\?agent_id=[^&]+&conversation_signature=/);
  assert.equal(new URL(url).searchParams.get('agent_id'), made.agent_id);
  const saved = { agent: made.agent_id, secret: secret.secret_id };
  writeFileSync(receiptFile, JSON.stringify(saved) + '\n');
  console.log(JSON.stringify({ spokenBytes: pcm.length, signedUrl: true, ...saved }));
}
